3	export function parse(v: string): Version {
4	  const m = /^(\d+)\.(\d+)\.(\d+)$/.exec(v);
5	  if (!m) throw new Error(`invalid version: ${v}`);
6	  return { major: Number(m[1]), minor: Number(m[2]), patch: Number(m[3]) };
7	}
8	
9	function cmp(a: Version, b: Version): number {
10	  return a.major - b.major || a.minor - b.minor || a.patch - b.patch;
11	}
12	
13	/** Orders two version strings numerically per component. */
14	export function compare(a: string, b: string): number {
15	  return cmp(parse(a), parse(b));
16	}
17	
18	type Op = '>=' | '>' | '<=' | '<' | '=';
19	interface Comparator {
20	  op: Op;
21	  v: Version;
22	}
23	
24	const v3 = (major: number, minor: number, patch: number): Version => ({ major, minor, patch });
25	const ge = (v: Version): Comparator => ({ op: '>=', v });
26	const lt = (v: Version): Comparator => ({ op: '<', v });
27	
28	/** Parses `1`, `1.2` or `1.2.3`; missing or `x` parts count as 0. Returns the version and how many parts were given. */
29	function partial(s: string): { v: Version; parts: number } {
30	  const bits = s.split('.');
31	  const nums = bits.map((b) => (b === 'x' || b === '*' ? -1 : Number(b)));
32	  if (bits.length > 3 || nums.some((n) => Number.isNaN(n))) throw new Error(`invalid range: ${s}`);
33	  const given = nums.findIndex((n) => n < 0);
34	  const parts = given === -1 ? nums.length : given;
35	  const [a = 0, b = 0, c = 0] = nums.map((n, i) => (i < parts ? n : 0));
36	  return { v: v3(a, b, c), parts };
37	}
38	
39	function bump(v: Version, level: 'major' | 'minor' | 'patch'): Version {
40	  if (level === 'major') return v3(v.major + 1, 0, 0);
41	  if (level === 'minor') return v3(v.major, v.minor + 1, 0);
42	  return v3(v.major, v.minor, v.patch + 1);
43	}
44	
45	function expand(token: string): Comparator[] {
46	  const m = /^(\^|~|>=|<=|>|<|=)?(.*)$/.exec(token)!;
47	  const { v, parts } = partial(m[2]);
48	  switch (m[1]) {
49	    case '^': {
50	      const level = v.major > 0 || parts < 3 ? 'major' : v.minor > 0 ? 'minor' : 'patch';
51	      return [ge(v), lt(bump(v, level))];
52	    }
53	    case '~':
54	      return [ge(v), lt(bump(v, parts <= 1 ? 'major' : 'minor'))];
55	    case '>=':
56	      return [ge(v)];
57	    case '>':
58	      return parts === 3 ? [{ op: '>', v }] : [ge(bump(v, parts === 2 ? 'minor' : 'major'))];
59	    case '<=':
60	      return [parts === 3 ? { op: '<=', v } : lt(bump(v, parts === 2 ? 'minor' : 'major'))];
61	    case '<':
62	      return [lt(v)];
63	    default:
64	      if (parts === 3) return [{ op: '=', v }];
65	      return parts === 0 ? [] : [ge(v), lt(bump(v, parts === 2 ? 'minor' : 'major'))];
66	  }
67	}
