69	/**
70	 * Supported range syntax: `*`/`x`, exact `1.2.3`, x-ranges `1.x` / `1.2.x`, `^`, `~`, `>=`, `>`, `<=`, `<`,
71	 * comparators joined by spaces (AND) and sets joined by `||` (OR).
72	 */
73	function compile(range: string): Comparator[][] {
74	  return range.split('||').map((set) => set.trim().split(/\s+/).filter(Boolean).flatMap(expand));
75	}
76	
77	function test(c: Comparator, v: Version): boolean {
78	  const d = cmp(v, c.v);
79	  switch (c.op) {
80	    case '>=': return d >= 0;
81	    case '>': return d > 0;
82	    case '<=': return d <= 0;
83	    case '<': return d < 0;
84	    default: return d === 0;
85	  }
86	}
87	
88	export function satisfies(version: string, range: string): boolean {
89	  const v = parse(version);
90	  return compile(range).some((set) => set.every((c) => test(c, v)));
91	}

