5	export class ResolveError extends Error {}
6	
7	/**
8	 * Resolves `root` (name -> range) against the registry. Every distinct (name, range) pair gets the highest
9	 * satisfying version; different ranges of one package may resolve to different versions, and all of them end
10	 * up in the result. Dependency cycles are allowed.
11	 */
12	export function resolve(root: Record<string, string>, registry: Registry): Resolution {
13	  const cache = new Map<string, string>();
14	  const nodes = new Map<string, Node>();
15	
16	  const pick = (name: string, range: string): string => {
17	    const id = name;
18	    let version = cache.get(id);
19	    if (version === undefined) {
20	      version = registry.versions(name).filter((v) => satisfies(v, range)).pop();
21	      if (version === undefined) throw new ResolveError(`no version of ${name} satisfies ${range}`);
22	      cache.set(id, version);
23	    }
24	    return version;
25	  };
26	
27	  const visit = (name: string, range: string): string => {
28	    const version = pick(name, range);
29	    const key = `${name}@${version}`;
30	    if (nodes.has(key)) return key;
31	    const m = registry.get(name, version);
32	    const node: Node = { name, version, key, deps: [], build: m.build };
33	    nodes.set(key, node); // registered before recursing so cycles terminate
34	    const deps = new Set<string>();
35	    for (const dep of Object.keys(m.deps).sort()) deps.add(visit(dep, m.deps[dep]));
36	    node.deps = [...deps].sort();
37	    return key;
38	  };
39	
40	  const roots = new Set<string>();
41	  for (const name of Object.keys(root).sort()) roots.add(visit(name, root[name]));
42	  return { roots: [...roots].sort(), nodes };
43	}

