3	export interface Ordering {
4	  order: string[];
5	  cycles: string[][];
6	}
7	
8	/** Rotates a closed path (first === last) so that it starts at its smallest key. */
9	function canonical(path: string[]): string[] {
10	  const ring = path.slice(0, -1);
11	  const at = ring.indexOf([...ring].sort()[0]);
12	  const rotated = [...ring.slice(at), ...ring.slice(0, at)];
13	  return [...rotated, rotated[0]];
14	}
15	
16	/**
17	 * Depth-first topological order: every key appears after its dependencies. Keys and dependencies are visited in
18	 * sorted order so the result is deterministic. A back edge closes a cycle; cycles are reported once each as a
19	 * closed path starting at the smallest key of the cycle, and are returned sorted. Edges into unknown keys are ignored.
20	 */
21	export function topoOrder(nodes: Map<string, Node>): Ordering {
22	  const order: string[] = [];
23	  const cycles = new Map<string, string[]>();
24	  const state = new Map<string, 'open' | 'done'>();
25	  const path: string[] = [];
26	
27	  const walk = (key: string): void => {
28	    state.set(key, 'open');
29	    path.push(key);
30	    for (const dep of nodes.get(key)!.deps) {
31	      if (!nodes.has(dep)) continue;
32	      const s = state.get(dep);
33	      if (s === 'open') {
34	        const loop = canonical([...path, dep]);
35	        cycles.set(loop.join('>'), loop);
36	      } else if (s === undefined) walk(dep);
37	    }
38	    path.pop();
39	    state.set(key, 'done');
40	    order.push(key);
41	  };
42	
43	  for (const key of [...nodes.keys()].sort()) if (!state.has(key)) walk(key);
44	  return { order, cycles: [...cycles.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([, c]) => c) };
45	}

