6	const MS_PER_DECISECOND = 1000;
7	
8	/** Resolves the dependencies of `root`, orders the builds and estimates the wall-clock time. */
9	export function plan(root: Pick<Manifest, 'deps'>, registry: Registry): Plan {
10	  const { nodes } = resolve(root.deps, registry);
11	  const { order, cycles } = topoOrder(nodes);
12	
13	  const level = new Map<string, number>();
14	  const waves: string[][] = [];
15	  for (const key of order) {
16	    const node = nodes.get(key)!;
17	    const at = 1 + Math.max(-1, ...node.deps.filter((d) => level.has(d)).map((d) => level.get(d)!));
18	    level.set(key, at);
19	    (waves[at] ??= []).push(key);
20	  }
21	  for (const wave of waves) wave.sort();
22	
23	  let deciseconds = 0;
24	  for (const wave of waves) deciseconds += Math.max(...wave.map((k) => nodes.get(k)!.build));
25	  return { order, waves, cycles, estimateMs: deciseconds * MS_PER_DECISECOND };
26	}

