3	/** In-memory package index. */
4	export class Registry {
5	  private pkgs = new Map<string, Map<string, Manifest>>();
6	
7	  add(m: Manifest): this {
8	    let versions = this.pkgs.get(m.name);
9	    if (!versions) this.pkgs.set(m.name, (versions = new Map()));
10	    versions.set(m.version, m);
11	    return this;
12	  }
13	
14	  /** All versions of `name`, lowest first (numeric semver order). Empty when the package is unknown. */
15	  versions(name: string): string[] {
16	    return [...(this.pkgs.get(name)?.keys() ?? [])].sort();
17	  }
18	
19	  get(name: string, version: string): Manifest {
20	    const m = this.pkgs.get(name)?.get(version);
21	    if (!m) throw new Error(`unknown package ${name}@${version}`);
22	    return m;
23	  }
24	}

