4	export function registry(spec: Array<[string, Record<string, string>, number?]>): Registry {
5	  const r = new Registry();
6	  for (const [id, deps, build] of spec) {
7	    const at = id.lastIndexOf('@');
8	    r.add({ name: id.slice(0, at), version: id.slice(at + 1), deps, build: build ?? 1 });
