3	/** `0s`, `5s`, `1m05s`, `2h00m07s`; rounds to the nearest second. */
4	export function formatDuration(ms: number): string {
5	  const total = Math.round(ms / 1000);
6	  const h = Math.floor(total / 3600);
7	  const m = Math.floor((total % 3600) / 60);
8	  const s = total % 60;
9	  const two = (n: number) => String(n).padStart(2, '0');
10	  if (h > 0) return `${h}h${two(m)}m${two(s)}s`;
11	  if (m > 0) return `${m}m${two(s)}s`;
12	  return `${s}s`;
13	}
